// app/todos/actions.ts
'use server'
import { refresh } from 'next/cache'
import { db } from '@/lib/db'
import { getSession } from '@/lib/auth'

export async function addTodo(prev: { error?: string }, formData: FormData) {
  const session = await getSession()
  if (!session) return { error: 'Please log in' }          // check auth in every action
  const title = String(formData.get('title') ?? '').trim()
  if (!title) return { error: 'Title is required' }        // expected error as a value
  await db.todo.create({ title, userId: session.userId })
  refresh()                                                // re-render with fresh data
  return {}
}

