// app/api/todos/[id]/route.ts
import { NextRequest } from 'next/server'

const todos = new Map([['1', { id: '1', title: 'Write docs', done: false }]])

export async function GET(_req: NextRequest, ctx: RouteContext<'/api/todos/[id]'>) {
  const { id } = await ctx.params
  const todo = todos.get(id)
  if (!todo) return Response.json({ error: 'Not found' }, { status: 404 })
  return Response.json(todo)                       // 200 {"id":"1",...}
}

export async function PATCH(request: NextRequest, ctx: RouteContext<'/api/todos/[id]'>) {
  const { id } = await ctx.params
  const body = await request.json()                // e.g. { "done": true }
  const todo = todos.get(id)
  if (!todo) return Response.json({ error: 'Not found' }, { status: 404 })
  if (typeof body.done !== 'boolean') {
    return Response.json({ error: 'done must be boolean' }, { status: 400 })
  }
  todo.done = body.done
  return Response.json(todo)
}

