// app/api/cms-webhook/route.ts
import { revalidateTag } from 'next/cache'

export async function POST(request: Request) {
  if (request.headers.get('x-webhook-secret') !== process.env.CMS_SECRET) {
    return new Response('Forbidden', { status: 403 })
  }
  const { postId } = await request.json()
  revalidateTag(`post:${postId}`, 'max')   // serve stale once, regenerate in background
  revalidateTag('posts', 'max')
  return Response.json({ revalidated: true })
}

// proxy.ts (project root)
import { NextResponse, type NextRequest } from 'next/server'

const protectedPrefixes = ['/dashboard', '/settings']

export function proxy(request: NextRequest) {
  const { pathname } = request.nextUrl
  const hasSession = request.cookies.has('session')

  // optimistic check only; real authorization happens next to the data
  if (protectedPrefixes.some((p) => pathname.startsWith(p)) && !hasSession) {
    const login = new URL('/login', request.url)
    login.searchParams.set('next', pathname)
    return NextResponse.redirect(login)
  }

  const response = NextResponse.next()
  response.headers.set('X-Frame-Options', 'DENY')
  return response
}

