// lib/dal.ts - Data Access Layer
import 'server-only'
import { cache } from 'react'
import { cookies } from 'next/headers'
import { redirect } from 'next/navigation'
import { decrypt } from '@/lib/session'
import { db } from '@/lib/db'

export const verifySession = cache(async () => {
  const token = (await cookies()).get('session')?.value
  const session = await decrypt(token)            // verify signature and expiry
  if (!session?.userId) redirect('/login')
  return { userId: session.userId as string, role: session.role as string }
})

export async function getInvoice(id: string) {
  const { userId, role } = await verifySession()
  const invoice = await db.invoice.find(id)
  if (!invoice || (invoice.ownerId !== userId && role !== 'admin')) return null
  // DTO: only what the UI needs, never internal fields
  return { id: invoice.id, amount: invoice.amount, status: invoice.status }
}

