// app/ui/nav-link.tsx - pending feedback while a navigation is in flight
'use client'
import Link, { useLinkStatus } from 'next/link'

function Spinner() {
  const { pending } = useLinkStatus()           // true while this link's navigation loads
  return pending ? <span aria-hidden> ...</span> : null
}

export function NavLink({ href, children }: { href: string; children: React.ReactNode }) {
  return (
    <Link href={href} prefetch={false}>         {/* rarely used: skip prefetch */}
      {children}
      <Spinner />
    </Link>
  )
}

