// app/items/[id]/page.tsx
import { db } from '@/lib/db'
import { verifySession } from '@/lib/dal'

export default async function ItemPage({ params }: PageProps<'/items/[id]'>) {
  const { id } = await params
  const item = await db.item.find(id)

  async function archive() {
    'use server'
    // `id` is a captured closure value: encrypted, sent to the client and back.
    // Still treat it as untrusted input: re-check the session and ownership here.
    const { userId } = await verifySession()
    const current = await db.item.find(id)
    if (current?.ownerId !== userId) throw new Error('Forbidden')
    await db.item.update({ where: { id }, data: { archived: true } })
  }

  return (
    <form action={archive}>                  {/* POST /items/42 with the action ID */}
      <h1>{item?.name}</h1> <button>Archive</button>
    </form>
  )
}
